// lib/lato-font.ts
// Fonte Lato (subconjunto português) embutida no PDF.
// Uso:  registrarLato(doc)  -> depois  doc.setFont("Lato", "normal" | "bold")
// Licença: SIL Open Font License 1.1 (Lato, tyPoland Lukasz Dziedzic).
import type { jsPDF } from "jspdf";

const LATO_REGULAR = "";
const LATO_BOLD = "";

export function registrarLato(doc: jsPDF) {
  doc.addFileToVFS("Lato-Regular.ttf", LATO_REGULAR);
  doc.addFont("Lato-Regular.ttf", "Lato", "normal");
  doc.addFileToVFS("Lato-Bold.ttf", LATO_BOLD);
  doc.addFont("Lato-Bold.ttf", "Lato", "bold");
}
